/**
 * knowledge-curator.ts — 知识生命周期管理器
 *
 * 进化引擎 30→100 核心模块。对标 Hermes Curator（agent/curator.py, 1801行）。
 *
 * Hermes Curator 模式：
 *   - 7天周期审查 → 自动检测陈旧知识 → 合并/归档
 *   - active → stale → archived → reactivated 四态生命周期
 *   - 快照+回滚（curator_backup.py）
 *   - Usage telemetry 驱动决策（.usage.json）
 *   - Provenance filtering（只管理 agent 创作的知识）
 *
 * Synova 适配：
 *   - 诊断知识项（规则、术语、基准、模式）替代技能文件
 *   - 组织级知识（Layer 2）→ 全局知识（Layer 3，联邦进化）
 *   - 知识代谢 = 陈旧规则自动降级 + 合并相似规则 + 归档过时规则
 */
export type KnowledgeState = 'active' | 'stale' | 'archived';
export type KnowledgeType = 'rule' | 'terminology' | 'benchmark' | 'pattern' | 'baseline';
export type KnowledgeSource = 'agent_derived' | 'user_confirmed' | 'federated' | 'bundled';
export interface KnowledgeItem {
    id: string;
    type: KnowledgeType;
    state: KnowledgeState;
    source: KnowledgeSource;
    orgId: string;
    /** 知识内容 */
    content: string;
    /** 关联维度 */
    dimensions: string[];
    /** 置信度 */
    confidence: number;
    /** 使用次数 */
    useCount: number;
    /** 验证次数（被后续诊断确认有效） */
    validationCount: number;
    /** 失效次数（被后续诊断推翻） */
    invalidationCount: number;
    /** 创建时间 */
    createdAt: string;
    /** 最后使用时间 */
    lastUsedAt: string;
    /** 最后验证时间 */
    lastValidatedAt?: string;
    /** 标记为 stale 的时间 */
    staleAt?: string;
    /** 归档时间 */
    archivedAt?: string;
    /** 是否锁定（锁定项不参与自动代谢） */
    pinned: boolean;
    /** 合并来源（如果是从其他知识项合并而来） */
    mergedFrom?: string[];
    /** 被合并到的目标 */
    mergedInto?: string;
}
export interface CuratorState {
    lastRunAt: string;
    lastRunDurationMs: number;
    lastRunSummary: string;
    runCount: number;
    paused: boolean;
}
export interface CuratorConfig {
    /** 审查间隔（小时），默认 168 = 7 天 */
    intervalHours: number;
    /** 标记 stale 天数 */
    staleAfterDays: number;
    /** 归档天数 */
    archiveAfterDays: number;
    /** 最小使用次数（低于此值的知识不参与合并） */
    minUseCountForConsolidation: number;
    /** 合并相似度阈值 */
    consolidationSimilarityThreshold: number;
}
export declare function addKnowledge(item: Omit<KnowledgeItem, 'id' | 'state' | 'useCount' | 'validationCount' | 'invalidationCount' | 'createdAt' | 'lastUsedAt'>): KnowledgeItem;
export declare function getKnowledge(id: string): KnowledgeItem | undefined;
export declare function listOrgKnowledge(orgId: string, state?: KnowledgeState): KnowledgeItem[];
export declare function updateKnowledge(id: string, patch: Partial<KnowledgeItem>): KnowledgeItem | null;
export declare function recordKnowledgeUse(id: string): void;
export declare function recordKnowledgeValidation(id: string, isValid: boolean): void;
export declare function applyAutoTransitions(orgId: string): {
    markedStale: number;
    archived: number;
    reactivated: number;
    checked: number;
};
export interface ConsolidationResult {
    consolidated: Array<{
        from: string[];
        into: string;
        reason: string;
    }>;
    pruned: Array<{
        id: string;
        reason: string;
    }>;
}
/**
 * 简单合并：同维度 + 同类型 + 内容相似 → 合并为一个，旧的归档。
 * 生产环境此函数应由 LLM 审查替代（对标 Hermes curator LLM review pass）。
 */
export declare function consolidateKnowledge(orgId: string): ConsolidationResult;
export declare function runCuratorPass(orgId: string): {
    autoTransitions: ReturnType<typeof applyAutoTransitions>;
    consolidations: ConsolidationResult;
    summary: string;
};
/** 检查是否应该运行策展审查 */
export declare function shouldRunCurator(orgId: string): boolean;
export declare function getCuratorState(orgId: string): CuratorState | undefined;
export declare function setCuratorConfig(orgId: string, config: Partial<CuratorConfig>): void;
/** 清空（测试用） */
export declare function clearCuratorStore(): void;
